-- PromRegion56 v5: годовые карточки Новотроицка, Орска и Оренбурга за 2021–2025 годы.
-- Повторно запускаемая миграция данных трех городов в существующую PostgreSQL БД.
-- Перед применением создайте резервную копию. Сторонние города и предприятия не удаляются.
BEGIN;
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,url=EXCLUDED.url,
 source_type=EXCLUDED.source_type,publication_date=EXCLUDED.publication_date,
 access_date=EXCLUDED.access_date,description=EXCLUDED.description;

WITH incoming(id,region,district,latitude,longitude,territory_type,oktmo,administrative_center) AS (
 VALUES (1,'Оренбургская область','городской округ город Новотроицк','51.203','58.3267','город','53720000001','Новотроицк'),
(2,'Оренбургская область','городской округ город Орск','51.2049','58.5668','город','53723000001','Орск'),
(3,'Оренбургская область','городской округ город Оренбург','51.7682','55.0969','город','53701000001','Оренбург')
)
UPDATE public.cities c SET region=i.region,district=i.district,
 latitude=i.latitude::double precision,longitude=i.longitude::double precision,
 territory_type=i.territory_type,oktmo=i.oktmo,administrative_center=i.administrative_center
FROM incoming i WHERE c.id=i.id;

CREATE TEMP TABLE _incoming_city_metrics(
 city_id integer,year integer,population integer,average_salary numeric,
 unemployment_rate numeric,investments numeric,industrial_output numeric,source_id integer
) ON COMMIT DROP;

UPDATE public.territory_metrics m SET population=v.population,
 average_salary=v.average_salary,unemployment_rate=v.unemployment_rate,
 investments=v.investments,industrial_output=v.industrial_output,source_id=v.source_id
FROM _incoming_city_metrics v WHERE m.city_id=v.city_id AND m.year=v.year;
 investments,industrial_output,source_id)
SELECT v.city_id,v.year,v.population,v.average_salary,v.unemployment_rate,
 v.investments,v.industrial_output,v.source_id FROM _incoming_city_metrics v
WHERE NOT EXISTS (SELECT 1 FROM public.territory_metrics m WHERE m.city_id=v.city_id AND m.year=v.year);

SELECT setval(pg_get_serial_sequence('public.data_sources','id'),GREATEST((SELECT max(id) FROM public.data_sources),1),true);
SELECT setval(pg_get_serial_sequence('public.territory_metrics','id'),GREATEST((SELECT max(id) FROM public.territory_metrics),1),true);

CREATE TABLE IF NOT EXISTS public.city_annual_indicators (
 city_id integer NOT NULL REFERENCES public.cities(id),
 year integer NOT NULL CHECK (year BETWEEN 2000 AND 2100),
 metric_code text NOT NULL,
 numeric_value numeric(20,4),
 unit text NOT NULL,
 source_metric_name text NOT NULL,
 verification_status text NOT NULL CHECK (verification_status IN ('reported','municipal_estimate','unavailable')),
 source_id integer REFERENCES public.data_sources(id),
 as_of_date date,
 coverage_note text NOT NULL DEFAULT '',
 PRIMARY KEY (city_id,year,metric_code)
);
ON CONFLICT(city_id,year,metric_code) DO UPDATE SET
 numeric_value=EXCLUDED.numeric_value,unit=EXCLUDED.unit,source_metric_name=EXCLUDED.source_metric_name,
 verification_status=EXCLUDED.verification_status,source_id=EXCLUDED.source_id,
 as_of_date=EXCLUDED.as_of_date,coverage_note=EXCLUDED.coverage_note;

COMMIT;

SELECT city_id,COUNT(*) FROM public.territory_metrics WHERE city_id IN (1,2,3) AND year BETWEEN 2021 AND 2025 GROUP BY city_id ORDER BY city_id;
SELECT city_id,COUNT(*),COUNT(*) FILTER (WHERE numeric_value IS NULL) AS unknowns FROM public.city_annual_indicators GROUP BY city_id ORDER BY city_id;
